use std::{
    env, fs,
    io::{self, Write},
    process,
    sync::mpsc,
};

use wgpu::util::DeviceExt;

/// Edge length of one compute workgroup along each axis.
const WORKGROUP: u32 = 16;

/// One generation of Conway's Game of Life. Each invocation decides one cell
/// from `src` and writes the result to `dst`, so no cell sees a value that the
/// current generation has already decided.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    let w = i32(params.width);
    let h = i32(params.height);
    var neighbours = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                neighbours += src[u32(ny) * params.width + u32(nx)];
            }
        }
    }

    let index = y * params.width + x;
    var alive = 0u;
    if (src[index] == 1u) {
        if (neighbours == 2u || neighbours == 3u) {
            alive = 1u;
        }
    } else if (neighbours == 3u) {
        alive = 1u;
    }
    dst[index] = alive;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut header = |name: &str| -> Result<u32, String> {
        let token = tokens.next().ok_or(format!("missing {name} in header"))?;
        token
            .parse::<u32>()
            .map_err(|_| format!("invalid {name} {token:?} in header"))
    };
    let width = header("width")?;
    let height = header("height")?;
    let generations = header("generations")?;

    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("grid size {width}x{height} is outside 1..=512"));
    }
    if generations > 1000 {
        return Err(format!("generations {generations} is outside 0..=1000"));
    }

    let mut cells = Vec::with_capacity((width * height) as usize);
    for token in tokens {
        for byte in token.bytes() {
            match byte {
                b'0' => cells.push(0),
                b'1' => cells.push(1),
                _ => return Err(format!("invalid cell {:?}", char::from(byte))),
            }
        }
    }
    let expected = (width * height) as usize;
    if cells.len() != expected {
        return Err(format!(
            "expected {expected} cells, found {}",
            cells.len()
        ));
    }

    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

fn to_bytes(values: &[u32]) -> Vec<u8> {
    values.iter().flat_map(|v| v.to_le_bytes()).collect()
}

/// Runs `generations` steps on the GPU and returns the final cells.
async fn simulate(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .map_err(|e| format!("no GPU adapter available: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let byte_len = (grid.width * grid.height) as u64 * 4;
    let storage_usage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_DST
        | wgpu::BufferUsages::COPY_SRC;

    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: &to_bytes(&[grid.width, grid.height]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    // Two buffers that swap roles each generation.
    let buffers = [0, 1].map(|i| {
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some(if i == 0 { "cells a" } else { "cells b" }),
            contents: &to_bytes(&grid.cells),
            usage: storage_usage,
        })
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: byte_len,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("life layout"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: true },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("life pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life pipeline"),
        layout: Some(&pipeline_layout),
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    // bind_groups[g] reads from buffers[g % 2] and writes to buffers[(g + 1) % 2].
    let bind_groups = [0, 1].map(|g| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("life bind group"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: buffers[g].as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: buffers[1 - g].as_entire_binding(),
                },
            ],
        })
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("life generations"),
    });
    let groups = (grid.width.div_ceil(WORKGROUP), grid.height.div_ceil(WORKGROUP));
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("life pass"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        for generation in 0..grid.generations as usize {
            pass.set_bind_group(0, &bind_groups[generation % 2], &[]);
            pass.dispatch_workgroups(groups.0, groups.1, 1);
        }
    }

    // After `generations` steps the newest cells sit in buffers[generations % 2 ^ 1]
    // is wrong to reason about; the last write went to buffers[generations % 2].
    let last = if grid.generations % 2 == 0 { 0 } else { 1 };
    encoder.copy_buffer_to_buffer(&buffers[last], 0, &readback, 0, byte_len);
    queue.submit(Some(encoder.finish()));

    let (tx, rx) = mpsc::channel();
    readback
        .slice(..)
        .map_async(wgpu::MapMode::Read, move |result| {
            let _ = tx.send(result);
        });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback channel closed: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let data = readback.slice(..).get_mapped_range();
    let cells = data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);
    readback.unmap();
    Ok(cells)
}

fn run() -> Result<(), String> {
    let path = env::args()
        .nth(1)
        .ok_or_else(|| "usage: gpu_life <input-file>".to_string())?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let grid = parse(&text)?;

    let cells = if grid.generations == 0 {
        grid.cells.clone()
    } else {
        pollster::block_on(simulate(&grid))?
    };

    let width = grid.width as usize;
    let mut out = String::with_capacity(cells.len() * 2 + grid.height as usize);
    let mut alive = 0usize;
    for row in cells.chunks(width) {
        let line: Vec<&str> = row
            .iter()
            .map(|&c| {
                alive += c as usize;
                if c == 1 { "1" } else { "0" }
            })
            .collect();
        out.push_str(&line.join(" "));
        out.push('\n');
    }
    out.push_str(&format!("ALIVE {alive}\n"));

    let mut stdout = io::stdout().lock();
    stdout
        .write_all(out.as_bytes())
        .and_then(|_| stdout.flush())
        .map_err(|e| format!("cannot write output: {e}"))
}

fn main() {
    if let Err(message) = run() {
        eprintln!("error: {message}");
        process::exit(1);
    }
}

